import React, { useEffect, useState } from "react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  CustomTextArea,
  DeleteIcon,
} from "../../../components";
import { getLoggedInUser } from "../../../helpers/authUtils";
import useApi from "../../../hooks/useApi";
import routesApi from "../../../api/drugs/routesApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import * as Yup from "yup";
import { useFormik } from "formik";
import { toast, ToastContainer } from "react-toastify";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";
import productsApi from "../../../api/productsApi";
import frequenciesApi from "../../../api/drugs/frequenciesApi";
import departmentsApi from "../../../api/departmentsApi";
import LaboratoryOrdersForm from "./LaboratoryOrdersForm";
import RadiologyOrdersForm from "./RadiologyOrdersForm";
import PhysiotherapyOrdersForm from "./PhysiotherapyOrdersForm";

export default function InternalReferral({ selectedDependant }) {
  const [user, setUser] = useState();
  const [errors, setErrors] = useState();
  const { currentColor, loggedInUser } = useStateContext();
  const [openLaboratoryOrder, setopenLaboratoryOrder] = useState();
  const [openRadiologyOrder, setopenRadiologyOrder] = useState();
  const [openPhysiotherapyOrder, setopenPhysiotherapyOrder] = useState();

  const [frequencies, setfrequencies] = useState([]);
  const getFrequenciesApi = useApi(frequenciesApi.frequenciesAction);
  const getFrequencies = async () => {
    await getFrequenciesApi.request({
      action: "GetFrequencies",
    });
  };

  useEffect(() => {
    if (getFrequenciesApi.data && getFrequenciesApi.data.length) {
      setfrequencies(
        getFrequenciesApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }
  }, [getFrequenciesApi.data]);

  const [routes, setroutes] = useState([]);
  const getRoutesApi = useApi(routesApi.routesAction);
  const getRoutes = async () => {
    await getRoutesApi.request({
      action: "GetRoutes",
    });
  };

  useEffect(() => {
    if (getRoutesApi.data && getRoutesApi.data.length) {
      setroutes(
        getRoutesApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }
  }, []);



  const [dependantLaboratoryOrders, setdependantLaboratoryOrders] = useState(
    []
  );
  const [dependantRadiologyOrders, setdependantRadiologyOrders] = useState([]);
  const [dependantPhysiotherapyOrders, setdependantPhysiotherapyOrders] = useState([]);




  //Retrieve laboratory orders

  const getDependantLaboratoryOrdersApi = useApi(
    hospitalsApi.hospitalStaffAction
  );
  const getDependantLaboratoryOrders = async () => {
    await getDependantLaboratoryOrdersApi.request({
      action: "GetDependantLaboratoryOrders",
      dependant: selectedDependant.id,
    });
  };

  useEffect(() => {
    if (
      getDependantLaboratoryOrdersApi.data &&
      getDependantLaboratoryOrdersApi.data.length
    ) {
      setdependantLaboratoryOrders(getDependantLaboratoryOrdersApi.data);
    }

    console.log(
      "getDependantLaboratoryOrdersApi.data",
      getDependantLaboratoryOrdersApi.data
    );
  }, [getDependantLaboratoryOrdersApi.data]);

  //Retrieve radiology orders

  const getDependantRadiologyOrdersApi = useApi(
    hospitalsApi.hospitalStaffAction
  );
  const getDependantRadiologyOrders = async () => {
    await getDependantRadiologyOrdersApi.request({
      action: "GetDependantRadiologyOrders",
      dependant: selectedDependant.id,
    });
  };

  useEffect(() => {
    if (
      getDependantRadiologyOrdersApi.data &&
      getDependantRadiologyOrdersApi.data.length
    ) {
      setdependantRadiologyOrders(getDependantRadiologyOrdersApi.data);
    }

    console.log(
      "getDependantRadiologyOrdersApi.data",
      getDependantRadiologyOrdersApi.data
    );
  }, [getDependantRadiologyOrdersApi.data]);

  useEffect(() => {
    if (dependantRadiologyOrders && dependantRadiologyOrders.length) {
      setopenPhysiotherapyOrder(
        dependantRadiologyOrders?.find((x) => x.is_closed === "false")
      );
    }
  }, [dependantRadiologyOrders]);
  //Retrieve radiology orders

  const getDependantPhysiotherapyOrdersApi = useApi(
    hospitalsApi.hospitalStaffAction
  );
  const getDependantPhysiotherapyOrders = async () => {
    await getDependantPhysiotherapyOrdersApi.request({
      action: "GetDependantPhysiotherapyOrders",
      dependant: selectedDependant.id,
    });
  };

  useEffect(() => {
    if (
      getDependantPhysiotherapyOrdersApi.data &&
      getDependantPhysiotherapyOrdersApi.data.length
    ) {
      setdependantPhysiotherapyOrders(getDependantPhysiotherapyOrdersApi.data);
    }

    console.log(
      "getDependantPhysiotherapyOrdersApi.data",
      getDependantPhysiotherapyOrdersApi.data
    );
  }, [getDependantPhysiotherapyOrdersApi.data]);

  useEffect(() => {
    if (dependantPhysiotherapyOrders && dependantPhysiotherapyOrders.length) {
      setopenPhysiotherapyOrder(
        dependantPhysiotherapyOrders?.find((x) => x.is_closed === "false")
      );
    }

    console.log("dependantPhysiotherapyOrders", dependantPhysiotherapyOrders)
  }, [dependantPhysiotherapyOrders]);

  //Create  laboratory departmental order

  const createdependantLaboratoryOrderApi = useApi(
    hospitalsApi.hospitalStaffAction
  );

  const createdependantLaboratoryOrder = async (data) => {
    setErrors([]);
    await createdependantLaboratoryOrderApi.request(data);
  };

  useEffect(() => {
    if (createdependantLaboratoryOrderApi.data) {
      if (createdependantLaboratoryOrderApi.data.response_code === 0) {
        toast.success(createdependantLaboratoryOrderApi.data.response_message);
      }

      if (createdependantLaboratoryOrderApi.data.response_code === 1) {
        toast.error(createdependantLaboratoryOrderApi.data.response_message);
      }

      if (createdependantLaboratoryOrderApi.data.laboratory_order) {
        setopenLaboratoryOrder(
          createdependantLaboratoryOrderApi.data.laboratory_order
        );
      }

      if (createdependantLaboratoryOrderApi.data.errors) {
        setErrors(createdependantLaboratoryOrderApi.data.errors);
      }
    }

    console.log(
      "createDepartmentalTransferApi.data",
      createdependantLaboratoryOrderApi.data
    );
  }, [createdependantLaboratoryOrderApi.data]);

  //Create  laboratory departmental order

  const createdependantRadiologyOrderApi = useApi(
    hospitalsApi.hospitalStaffAction
  );



  useEffect(() => {
    if (createdependantRadiologyOrderApi.data) {
      if (createdependantRadiologyOrderApi.data.response_code === 0) {
        toast.success(createdependantRadiologyOrderApi.data.response_message);
      }

      if (createdependantRadiologyOrderApi.data.radiology_order) {
        setopenRadiologyOrder(
          createdependantRadiologyOrderApi.data.radiology_order
        );
      }

      if (createdependantRadiologyOrderApi.data.response_code === 1) {
        toast.error(createdependantRadiologyOrderApi.data.response_message);
      }

      if (createdependantRadiologyOrderApi.data.errors) {
        setErrors(createdependantRadiologyOrderApi.data.errors);
      }
    }

    console.log(
      "createdependantRadiologyOrderApi.data",
      createdependantRadiologyOrderApi.data
    );
  }, [createdependantRadiologyOrderApi.data]);




  //Retrieve departments
  const [departments, setDepartments] = useState([]);
  const entityDepartmentsApi = useApi(departmentsApi.departmentsAction);
  const getEntityDepartments = async (user) => {
    await entityDepartmentsApi.request({
      action: "GetEntityDepartments",
      entity: user.entity_id,
    });
  };


  useEffect(() => {
    if (user != null) {
      getEntityDepartments(user);
    }
    console.log("userr", user);
  }, [user]);




  useEffect(() => {
    if (entityDepartmentsApi.data && entityDepartmentsApi.data.length) {
      setDepartments(
        entityDepartmentsApi.data
          .filter((x) => x.id !== user.employment_department)
          .map((i) => ({
            label: i.title,
            value: i.id,
            department_type: i.department_type,
          }))
      );
    }
    console.log("entityDepartmentsApi", entityDepartmentsApi.data);
  }, [entityDepartmentsApi.data]);

  useEffect(() => {
    setUser(getLoggedInUser());
    getDependantLaboratoryOrders();
    getDependantRadiologyOrders();
    getDependantPhysiotherapyOrders();

  }, []);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  useEffect(() => {
    if (dependantLaboratoryOrders && dependantLaboratoryOrders.length) {
      setopenLaboratoryOrder(
        dependantLaboratoryOrders?.find((x) => x.is_closed === "false")
      );
    }
  }, [dependantLaboratoryOrders]);

  //Create dependant order
  const createDependantOrderApi = useApi(hospitalsApi.hospitalStaffAction);

  const createDependantOrder = async (data) => {
    setErrors([])
    await createDependantOrderApi.request(data);
  };

  useEffect(() => {
    if (createDependantOrderApi.data) {
      if (createDependantOrderApi.data.physiotherapy_order) {
        setopenPhysiotherapyOrder(createDependantOrderApi.data.physiotherapy_order)
      }
      if (createDependantOrderApi.data.radiology_order) {
        setopenRadiologyOrder(createDependantOrderApi.data.radiology_order)
      }
      if (createDependantOrderApi.data.laboratory_order) {
        setopenLaboratoryOrder(createDependantOrderApi.data.laboratory_order)
      }

      if (createDependantOrderApi.data.errors) {
        setErrors(createDependantOrderApi.data.errors)
      }

      if (createDependantOrderApi.data.response_code === "1") {
        getDependantLaboratoryOrders()
        getDependantRadiologyOrders()
        getDependantPhysiotherapyOrders()
      }

    }
    console.log("createDependantOrderApi.data", createDependantOrderApi.data)
  }, [createDependantOrderApi.data])


  // Create admission
  const createAdmissionApi = useApi(hospitalsApi.hospitalInpatientAction)
  const createAdmission = async (data) => {
    await createAdmissionApi.request(data)
  }

  useEffect(() => {
    console.log("createAdmissionApi.data", createAdmissionApi.data)
  }, [createAdmissionApi.data])

  const prescriptionFormik = useFormik({
    initialValues: {
      department: "",
    },

    validationSchema: Yup.object({
      department: Yup.object().required("Select destination department"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      let data = null;


      if (values.department.department_type === "LABORATORY") {
        toast.success("Pathology");
        data = {
          action: "CreateLaboratoryOrder",
          department: values.department.value,
          dependant: selectedDependant.id,
        };

      } else if (values.department.department_type === "RADIOLOGY") {

        data = {
          action: "CreateRadiologyOrder",
          department: values.department.value,
          dependant: selectedDependant.id,
          referral_comment: values.referral_comment
        };
      } else if (values.department.department_type === "RADIOLOGY") {
        toast.success("Physiotherapy");
      } else if (values.department.department_type === "WARD") {
        toast.success("Admission");
        data = {
          "action": "CreateAdmission",
          "dependant": selectedDependant.id,
          origin_department: loggedInUser.employment_department,
          destination_department: values.department.value,
          "referral_comment": values.referral_comment
        }
        createAdmission(data)
        return;

      } else if (values.department.department_type === "PHYSIOTHERAPY") {
        data = {
          action: "CreatePhysiotherapyOrder",
          origin_department: loggedInUser.employment_department,
          destination_department: values.department.value,
          dependant: selectedDependant.id,
          referral_comment: values.referral_comment
        };
      }

      console.log("data at create order", data)

      createDependantOrder(data)
    },
  });

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);





  return (
    <div className="grid grid-cols-2 md:grid-cols-12 mt-5 md:mt-1 mx-5">
      <div className="col-span-0 hidden md:block"></div>
      <div className="col-span-12 bg-gray-100 w-full ">
        <p className="text-center text-2xl font-bold">
          Inter-Departmental Referral
        </p>
        <ToastContainer theme="colored" position="bottom-center" />

        {selectedDependant ? (
          <div className="grid grid-cols-2 md:grid-cols-4 bg-white border-2 border-gray-400 rounded-md mx-2">
            <div className=" border-1 border-gray-300 p-2">
              <p>Name</p>
              <p>{selectedDependant.title}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Gender</p>
              <p>{selectedDependant.gender}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Date of Birth</p>
              <p>{selectedDependant.date_of_birth}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Age</p>
              <p>{selectedDependant.age} Years</p>
            </div>
          </div>
        ) : (
          <div></div>
        )}

        <div>
          <div className=" rounded-sm border-gray-200 mt-5 border-2 bg-white">
            <p className="text-center text-xl font-semibold">
              Add New Departmental Order
            </p>
            <CustomForm
              layout="horizontal"
              handleFinish={prescriptionFormik.handleSubmit}
              className="grid grid-cols-1 md:grid-cols-3 gap-4  justify-center items-center w-full px-2 "
            >
              <CustomFormItem
                className="w-full h-14"
                touched={prescriptionFormik.touched.department}
                error={prescriptionFormik.errors.department}
              >
                <CustomSelectReactSelect
                  className="text-start w-full h-full"
                  name="department"
                  id="department"
                  label="Select destination department"
                  size="large"
                  onChange={(value) =>
                    prescriptionFormik.setFieldValue("department", value)
                  }
                  value={prescriptionFormik.values.department}
                  placeholder="Select destination department"
                  options={departments}
                />
              </CustomFormItem>

              <CustomFormItem
                touched={prescriptionFormik.touched.referral_comment}
                error={prescriptionFormik.errors.referral_comment}
              >
                <CustomTextArea
                  className="text-start"
                  id="referral_comment"
                  name="referral_comment"
                  onChange={prescriptionFormik.handleChange}
                  placeholder="Enter referral comment (optional)"
                  label="Enter referral comment (optional)"
                  size="large"
                  type="text"
                  value={prescriptionFormik.values.referral_comment}
                />
              </CustomFormItem>

              <button
                id="formikPrescription"
                style={{ background: currentColor }}
                className="w-full h-12  rounded-md m-auto text-white self-center flex-1"
                color="primary"
                type="submit"
              >
                Submit
              </button>
            </CustomForm>
          </div>

          {openLaboratoryOrder ? (
            <LaboratoryOrdersForm
              openLaboratoryOrder={openLaboratoryOrder}
              setopenLaboratoryOrder={setopenLaboratoryOrder}
            />
          ) : (
            <div></div>
          )}
          {openRadiologyOrder ? (
            <RadiologyOrdersForm
              openRadiologyOrder={openRadiologyOrder}
              setopenRadiologyOrder={setopenLaboratoryOrder}
            />
          ) : (
            <div></div>
          )}
          {openPhysiotherapyOrder ? (
            <PhysiotherapyOrdersForm
              openPhysiotherapyOrder={openPhysiotherapyOrder}
              setopenPhysiotherapyOrder={setopenPhysiotherapyOrder}
            />
          ) : (
            <div></div>
          )}
        </div>
        <div className="flex items-center justify-center flex-col">
          <p className="text-xl font-semibold text-start ">Recent Pathology Orders</p>
          {dependantLaboratoryOrders && dependantLaboratoryOrders.length ? (
            <div className="text-xl my-2 p-2">
              {dependantLaboratoryOrders.map((order) => {
                return (
                  <div className="border-2 border-r-gray-200 rounded-md shadow-md bg-white">
                    <div className="grid grid-cols-2 font-bold  uppercase">
                      <p>{order.created}</p>
                      <p>
                        <span className="mx-1">Is Closed</span>
                        <span className="mx-1">{order.is_closed}</span>
                      </p>
                    </div>

                    <div >
                      {order.examinations ? (
                        <div>
                          {order.examinations.map((item,index) => {
                            return (
                              <div className="grid grid-cols-4">
                              <p>{parseInt(index+1).toString()+"."}</p>
                                <p>{item.examination_name}</p>
                                <p>Charge:{item.examination_charge}</p>
                                <p>Result:{item.result}</p>
                              </div>
                            );
                          })}
                        </div>
                      ) : (
                        <div>No Items in order</div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          ) : (
            <div>
              <p>No recent laboratory orders</p>
            </div>
          )}
        </div>
        <div className="flex items-center justify-center flex-col">
          <p className="text-xl font-semibold text-start ">Recent Radiology Orders</p>
        {dependantRadiologyOrders && dependantRadiologyOrders.length ? (
          <div className="text-2xl my-2 p-2" >
            {dependantRadiologyOrders.map((order) => {
              return (
                <div className="border-2 border-r-gray-200 rounded-md shadow-md bg-white">
                  <div className="grid grid-cols-2 font-bold  uppercase">
                    <p>{order.created}</p>
                    <p>
                      <span className="mx-1">Is Closed</span>
                      <span className="mx-1">{order.is_closed}</span>
                    </p>
                  </div>

                  <div>
                    {order.examinations ? (
                      <div>
                        {order.examinations.map((item,index) => {
                          return (
                            <div className="grid grid-cols-4">
                              <p>{parseInt(index+1).toString()+"."}</p>
                              <p>{item.examination_title}</p>
                              <p>Charge:{item.examination_charge}</p>
                              <p>Result:{item.result}</p>
                            </div>
                          );
                        })}
                      </div>
                    ) : (
                      <div>No Items in order</div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div>
            <p>No recent laboratory orders</p>
          </div>
        )}
      </div>
        <div className="flex flex-col items-center justify-center">
          <p className="text-xl font-semibold text-start">Recent Physiotherapy Orders</p>
          {dependantPhysiotherapyOrders && dependantPhysiotherapyOrders.length ? (
            <div></div>
          ) : (
            <div>
                <p>No recent physiotherapy orders</p>
            </div>
          )}
        </div>
      </div>
      <div className="col-span-0 hidden md:block"></div>
    </div>
  );
}
