import React, { useEffect, useState } from "react";
import {
  CustomForm,
  CustomInput,
  DeleteIcon,
  YesNoModal,
} from "../../../components";
import { useFormik } from "formik";
import * as Yup from "yup";
import { toast, ToastContainer } from "react-toastify";
import { Button, Card, Flex, Table } from "antd";
import useApi from "../../../hooks/useApi";
import productsApi from "../../../api/productsApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";

export default function RadiologyOrdersForm({
  openRadiologyOrder,
  setopenRadiologyOrder,
  selectedDependant,
}) {
  const columns = [
    {
      title: "Service Title",
      dataIndex: "radiology_service_title",
      render: (text) => <a>{text}</a>,
    },
    {
      title: "Charges",
      dataIndex: "charge",
      render: (text) => <a>{text}</a>,
    },

  ];
  const [user, setuser] = useState();
  const [searchText, setsearchText] = useState("");
  const [yesNoModal, setyesNoModal] = useState(false);
  const [mylocalOrder, setmylocalOrder] = useState(openRadiologyOrder)

  const [radiologyServices, setradiologyServices] = useState();
  const [preparationsData, setpreparationsData] = useState([]);
  const [selectedExamination, setselectedExamination] = useState();
  const { currentColor } = useStateContext();


  //Delete radiology examination froim radiology order
  const deleteRadiologyExaminationApi=useApi(hospitalsApi.hospitalStaffAction)
  const handleDeleteRadiologyExaminationAction = (item) => {
    console.log("item to delete",item)
    deleteRadiologyExaminationApi.request({
        "action":"DeleteRadiologyExamination",
        "radiology_examination":item.id
    })
  };

  useEffect(() => {
    if (deleteRadiologyExaminationApi.data) {
      if (
        deleteRadiologyExaminationApi.data.radiology_order
       
      ) {
        toast.success(deleteRadiologyExaminationApi.data.response_message);
        setselectedExamination(null);

      } else {
        toast.error(deleteRadiologyExaminationApi.data.response_message);
        setselectedExamination(null);
      }
    }
    console.log("deleteRadiologyExaminationApi.data",deleteRadiologyExaminationApi.data)
  }, [deleteRadiologyExaminationApi.data]);




  const prescriptionFormik = useFormik({
    initialValues: {
      facility_sub_store: "",
    },

    validationSchema: Yup.object({
      facility_sub_store: Yup.object().required("Select destination pharmacy"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);

      const data = {
        action: "CreateHospitalPrescription",
        department: user.employment_department,
        dependant: selectedDependant.id,
        facility_sub_store: values.facility_sub_store.value,
      };

      console.log("datume", data);

      resetForm();
    },
  });

  //Search generics
  const handleChange = (e) => {
    console.log("change", e.target.value);
    setsearchText(e.target.value);
  };

  //Search Radiology Examinations

  const getEntityRadiologyServicesApi = useApi(hospitalsApi.hospitalStaffAction);

  const retrieveDepartmentServices = async (data) => {
    setradiologyServices([]);
    // setselectedPreparation(null);

    await getEntityRadiologyServicesApi.request({
      action: "GetEntityRadiologyServices",
      department: mylocalOrder.department,
    });
  };

  useEffect(() => {
    if (getEntityRadiologyServicesApi.data && getEntityRadiologyServicesApi.data.length) {
      setradiologyServices(getEntityRadiologyServicesApi.data);
    }
    console.log("getEntityRadiologyServicesApi.data",getEntityRadiologyServicesApi.data)
  }, [getEntityRadiologyServicesApi.data]);

  useEffect(() => {
    if (searchText !== "") {
      handleFilter(searchText);
    }
  }, [searchText]);




  useEffect(() => {
    retrieveDepartmentServices(searchText);
  }, []);

  //Handle selection
  const [selectedRowKeys, setSelectedRowKeys] = useState([]);
  const [errors, setErrors] = useState([])

  const onSelectChange = (newSelectedRowKeys, selectedRow) => {
    setselectedExamination(selectedRow[0]);
    setSelectedRowKeys(newSelectedRowKeys);
  };

  useEffect(() => {
    if (selectedExamination) {
      setyesNoModal(true);
    }
  }, [selectedExamination]);
  const rowSelection = {
    selectedRowKeys,
    onChange: onSelectChange,
  };

  useEffect(() => {
    setpreparationsData(radiologyServices);
  }, [radiologyServices]);

  const handleFilter = (e) => {
    const search_param = e;

    if (
      radiologyServices &&
      radiologyServices.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setpreparationsData(
        radiologyServices.filter((x) =>
          x.radiology_service_title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setpreparationsData(radiologyServices);
    }
  };

  useEffect(() => {
    if (selectedExamination) {
      toast.success(selectedExamination.radiology_service_title);
      setyesNoModal(true);
    }
  }, [selectedExamination]);

  const createRadiologyExaminationApi = useApi(
    hospitalsApi.hospitalStaffAction
  );

  const addItemToOrder = async () => {
  
    setyesNoModal(false);

      await createRadiologyExaminationApi.request({
        action: "CreateRadiologyExamination",
        radiology_order: mylocalOrder.id,
        examination: selectedExamination.id,
      });
    
  };

  useEffect(() => {
    if (createRadiologyExaminationApi.data) {
      if (
        createRadiologyExaminationApi.data.radiology_order
       
      ) {
        toast.success(createRadiologyExaminationApi.data.response_message);
        setselectedExamination(null);
        setmylocalOrder(createRadiologyExaminationApi.data.radiology_order)
      } else {
        toast.error(createRadiologyExaminationApi.data.response_message);
        setselectedExamination(null);
        
      }
    }
    console.log("createRadiologyExaminationApi.data",createRadiologyExaminationApi.data)
  }, [createRadiologyExaminationApi.data]);




  //Update radiology order
  
  const updateRadiologyOrderApi=useApi(hospitalsApi.hospitalStaffAction)

  const handleCloseRadiologyOrder=async()=>{
    await updateRadiologyOrderApi.request({
        "action":"UpdateRadiologyOrder",
      "radiology_order": openRadiologyOrder.id,
        "is_closed":"true"
     
    })
  }


      useEffect(() => {
        if (errors && errors.length) {
          errors.map((x) => {
            toast.error(x);
          });
        }
      }, [errors]);

  useEffect(()=>{

    if(updateRadiologyOrderApi.data ){
        if(updateRadiologyOrderApi.data.radiology_order){
            toast.success(updateRadiologyOrderApi.data.response_message)
            setmylocalOrder(null)
            setopenRadiologyOrder(null)
        }

        if(updateRadiologyOrderApi.data.errors){
          
            setErrors(updateRadiologyOrderApi.data.errors)
        }
    }

    console.log("updateRadiologyOrderApi.data",updateRadiologyOrderApi.data)
  },[updateRadiologyOrderApi.data])



  return (
    <div className="w-full  border-1 border-gray-200 shadow-sm rounded-sm px-2 my-2">
    <ToastContainer theme="colored" position="bottom-center"/>
      <p className="text-2xl font-semibold text-center my-2">
        Radiology Requisitions
      </p>
      <CustomForm
        className=" my-5 md:w-full"
        layout="vertical"
        handleFinish={prescriptionFormik.handleSubmit}
      >
        <div className="border-2 border-gray-400 rounded-md my-5 p-5">
          <p className="text-1xl font-semibold text-center my-2">
            Add Radiology Examination
          </p>
          <div className="grid grid-cols-1  gap-2">
            <div className="col-span-8 bg-gray-50 p-5">
              <ToastContainer theme="colored" position="bottom-center" />
              <CustomInput
                className="w-full h-14 mt-5"
                size="large"
                id="search"
                name="search"
                label="Search radiology examination by name"
                placeholder="Search radiology examination by name"
                onChange={handleChange}
                value={searchText}
              />
              <div>
                <Flex className="mt-5" gap="middle" vertical>
                  <Table
                    rowSelection={{
                      type: "radio",
                      ...rowSelection,
                    }}
                    columns={columns}
                    dataSource={preparationsData}
                  />

                  {yesNoModal && selectedExamination && (
                    <YesNoModal
                      showModal={yesNoModal}
                      setyesNoModal={setyesNoModal}
                      title={selectedExamination.radiology_service_title}
                      content={"Add this item to order"}
                      yesAction={addItemToOrder}
                    />
                  )}
                  {mylocalOrder ? (
                    <div className="w-full">
                    <p className="text-1xl font-semibold text-center my-2">
                    Ordered Radiology Examinations
                  </p>
                      <div>
                        {mylocalOrder &&
                          mylocalOrder.examinations &&
                          mylocalOrder.examinations.length &&
                          mylocalOrder.examinations.map((x, index) => {
                            return (
                              <Card>
                                <div className="grid md:grid-cols-3 grid-cols-2">
                                  <div className="flex flex-col border-1 border-gray-200 p-2">
                                    <p>ITEM</p>
                                    <p className="font-bold">{x.examination_title}</p>
                                  </div>
                                  <div className="flex flex-col border-1 border-gray-200 p-2">
                                    <p>CHARGE</p>
                                    <p className="font-bold">KES {x.examination_charge.toString()}</p>
                                  </div>
                      

                                  <div className="flex flex-col border-1 border-gray-200 p-2 items-center justify-center">
                                    <p>REMOVE</p>
                                    <span className="text-lg text-default-400 cursor-pointer active:opacity-50  justify-center">
                                      <DeleteIcon
                                        onClick={() => handleDeleteRadiologyExaminationAction(x)}
                                      />
                                    </span>
                                  </div>
                                </div>
                              </Card>
                            );
                          })}
                      </div>
                    </div>
                  ) : (
                    <div></div>
                  )}
                </Flex>
              </div>
            </div>
          </div>
        </div>

        <div className="flex w-full items-center mt-2 justify-center col-span-1 md:col-span-2">
          <Button
            style={{
              background: currentColor,
              color: "white",
              width: 123,
              height: 50,
            }}
            onClick={()=>handleCloseRadiologyOrder()}
            className="w-40 rounded-md"
            color="primary"
            type="default"
          >
            Confirm and Close
          </Button>
        </div>
      </CustomForm>
    </div>
  );
}
